let flags = 0;
if (usePublic) {
  flags |= RNPLib.RNP_LOAD_SAVE_PUBLIC_KEYS;
}
if (useSecret) {
  flags |= RNPLib.RNP_LOAD_SAVE_SECRET_KEYS;
}

if (permissive) {
  flags |= RNPLib.RNP_LOAD_SAVE_PERMISSIVE;
}

let rv = RNPLib.rnp_import_keys(
  ffi,
  input_from_memory,
  flags,
  jsonInfo.address()
);
